import http.server as h
class H(h.SimpleHTTPRequestHandler):
    def end_headers(self):
        self.send_header('Cache-Control', 'no-cache')  # plain http.server sends none, so Chrome guesses a lifetime and serves stale JS after an edit
        super().end_headers()
h.ThreadingHTTPServer(('', 8080), H).serve_forever()
